package com.srent.ct01;
import com.srent.booking.Booking; import com.srent.common.BaseEntity; import com.srent.user.User; import jakarta.persistence.*; import lombok.*; import java.time.LocalDate;
@Entity @Table(name="ct01_forms") @Getter @Setter @NoArgsConstructor
public class Ct01Form extends BaseEntity { @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="student_id",nullable=false) private User student; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="booking_id",nullable=false) private Booking booking; @Column(name="full_name",nullable=false) private String fullName; @Column(name="date_of_birth",nullable=false) private LocalDate dateOfBirth; @Column(name="identity_number",nullable=false) private String identityNumber; private String phone; @Column(name="current_address",nullable=false) private String currentAddress; @Column(name="requested_address",nullable=false) private String requestedAddress; @Column(name="request_content",nullable=false) private String requestContent; @Column(name="additional_data") private String additionalData; @Version private long version; }
